draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+20);
  ctx.lineTo(W/2-150, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-120, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-180, H/2+80);
  ctx.stroke();

  // Draw lightbulb
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2-80+20*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-80+20*Math.sin(t));
  ctx.lineTo(W/2-150, H/2-60);
  ctx.stroke();

  ctx.restore();
}
